    for omitted_dimension in BEHAVIORAL_DIMENSIONS:
        print(
            f"\n{dataset_name}: removing "
            f"{omitted_dimension}"
        )

        for fold in range(1, 6):
            training = development[
                development["cv_fold"] != fold
